"""Random mixes of genuinely valid integers and near-miss tokens that look
numeric but are not valid ints."""


def _valid(rng):
    return str(rng.randint(-1000000, 1000000))


def _invalid(rng):
    choices = ["3.5", "0x1F", "1e3", "abc", "", "12a", "--5", "1 2", "NaN"]
    return rng.choice(choices)


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(1, 12)
    tokens = [(_valid(rng) if rng.random() < 0.6 else _invalid(rng))
             for _ in range(n)]
    lines = [str(n)] + tokens
    return {"name": "%d mixed tokens #%d" % (n, index),
            "stdin": "\n".join(lines) + "\n"}
